import{_ as l,o as a,c as i,a2 as e}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"个人网关与多入口","description":"Hearth Personal Gateway 的渠道归一化、事件去重、注意力收件箱、设备注册与手机接入。","frontmatter":{"title":"个人网关与多入口","description":"Hearth Personal Gateway 的渠道归一化、事件去重、注意力收件箱、设备注册与手机接入。","outline":[2,3]},"headers":[],"relativePath":"architecture/gateway.md","filePath":"architecture/gateway.md","lastUpdated":1793706118000}'),d={name:"architecture/gateway.md"};function r(o,t,n,s,p,h){return a(),i("div",null,[...t[0]||(t[0]=[e('<p class="eyebrow">PERSONAL GATEWAY</p><h1 id="个人网关与多入口" tabindex="-1">个人网关与多入口 <a class="header-anchor" href="#个人网关与多入口" aria-label="Permalink to &quot;个人网关与多入口&quot;">​</a></h1><p class="lead">用户、邮件、日历、IM、GitHub、网页、文件和设备如何被归一化为可去重、可追踪的事件。</p><h2 id="personal-gateway-与多入口" tabindex="-1">Personal Gateway 与多入口 <a class="header-anchor" href="#personal-gateway-与多入口" aria-label="Permalink to &quot;Personal Gateway 与多入口&quot;">​</a></h2><p>Personal Gateway 是 Hearth 与外部世界之间的唯一入口。它负责：</p><ul><li>识别用户、设备和渠道；</li><li>接收文字、语音、文件、图片、网页、邮件、日历和定时事件；</li><li>统一转换为 <code>Event</code>；</li><li>去重、排序、限流和来源标记；</li><li>判断哪些事件进入注意力收件箱；</li><li>维护设备注册、在线状态和配对关系；</li><li>为手机提供安全 API 和推送，而不是暴露本地端口。</li></ul><p>Gateway 不做长任务推理，也不直接执行业务动作。</p><h3 id="输入渠道" tabindex="-1">输入渠道 <a class="header-anchor" href="#输入渠道" aria-label="Permalink to &quot;输入渠道&quot;">​</a></h3><table tabindex="0"><thead><tr><th>渠道</th><th>典型输入</th><th>处理方式</th></tr></thead><tbody><tr><td>CLI</td><td>命令、脚本、开发调试</td><td>直达 Gateway，可结构化输出</td></tr><tr><td>Web/PWA</td><td>文本、文件、拖拽、分享</td><td>任务卡和审批中心</td></tr><tr><td>手机</td><td>文本、语音、分享、拍照、通知</td><td>审批、查看、接管、发起</td></tr><tr><td>IM</td><td>消息、文件、转发</td><td>Channel Adapter 归一化</td></tr><tr><td>Email</td><td>邮件与附件</td><td>只读同步、草稿、待审批发送</td></tr><tr><td>Calendar</td><td>日程与邀请</td><td>只读、冲突检查、待审批写入</td></tr><tr><td>Device</td><td>文件、屏幕、摄像头、传感器</td><td>设备能力与授权</td></tr><tr><td>Cron/Watch</td><td>定时器、文件变化、网页变化</td><td>Trigger 评估</td></tr><tr><td>API/MCP</td><td>外部服务事件</td><td>Connector 归一化</td></tr></tbody></table><p>第一阶段先设计渠道模型和界面状态，并在 MVP 中接 Web 与命令行；第二阶段再接第一个真实外部来源。不能一开始就铺所有渠道。</p><h3 id="事件归一化与去重" tabindex="-1">事件归一化与去重 <a class="header-anchor" href="#事件归一化与去重" aria-label="Permalink to &quot;事件归一化与去重&quot;">​</a></h3><p>所有渠道事件至少包含：</p><ul><li>来源类型与来源 id；</li><li>可信级别；</li><li>用户/设备身份；</li><li>原始时间；</li><li>内容引用或脱敏摘要；</li><li>会话/线程关联；</li><li>幂等键；</li><li>是否允许触发主动任务。</li></ul><p>默认策略：</p><ul><li>同一来源同一事件只处理一次；</li><li>重复通知合并；</li><li>低价值事件只记录，不推理；</li><li>不可信来源不能创建高风险 Mandate；</li><li>外部内容不能覆盖系统 Policy。</li></ul><h3 id="注意力收件箱" tabindex="-1">注意力收件箱 <a class="header-anchor" href="#注意力收件箱" aria-label="Permalink to &quot;注意力收件箱&quot;">​</a></h3><p>Attention Inbox 不是消息列表，而是“需要人处理的最小集合”：</p><ul><li>需要审批的动作；</li><li>需要补充信息的任务；</li><li>失败且无法自动恢复的任务；</li><li>需要接管的浏览器或桌面；</li><li>已完成的产物；</li><li>可延后查看的摘要。</li></ul><p>默认不进入收件箱：低置信度但无副作用的观察、被规则过滤的重复事件、纯状态变化、不需要人决策的失败重试。</p><p>排序依据：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>priority = risk × blockedness × deadline × userImpact × reversibilityPenalty</span></span></code></pre></div><p>用户关闭某渠道后，任何其他渠道都不能绕过。</p><h3 id="设备注册与能力目录" tabindex="-1">设备注册与能力目录 <a class="header-anchor" href="#设备注册与能力目录" aria-label="Permalink to &quot;设备注册与能力目录&quot;">​</a></h3><p>设备注册时上报：</p><ul><li>设备 id 与公钥；</li><li>操作系统和版本；</li><li>在线状态与心跳；</li><li>可用能力：文件、终端、浏览器、屏幕、摄像头、麦克风、通知、剪贴板；</li><li>可访问的本地数据范围；</li><li>安全边界和 Sandbox 支持；</li><li>用户授予的 capability；</li><li>设备 lease 与过期时间。</li></ul><p>设备能力不是永久授权。任务结束后，临时能力应自动回收。</p><h3 id="手机接入" tabindex="-1">手机接入 <a class="header-anchor" href="#手机接入" aria-label="Permalink to &quot;手机接入&quot;">​</a></h3><p>手机是 Hearth 的远程入口，不是默认执行权威。第四阶段的第一版只支持：</p><ol><li>查看任务、状态和产物；</li><li>审批高风险动作；</li><li>接管异常任务；</li><li>发起新任务；</li><li>接收高信号通知。</li></ol><p>安全要求：</p><ul><li>通过安全隧道或推送服务接入；</li><li>不直接暴露 Agent 端口；</li><li>设备配对使用短期码和公钥；</li><li>审批绑定 nonce、动作参数和过期时间；</li><li>通知只包含脱敏摘要；</li><li>设备丢失可撤销全部 token 和 lease。</li></ul>',31)])])}const b=l(d,[["render",r]]);export{u as __pageData,b as default};
